examples.template:
VStack(spacing: MonarchTokens.Space.space3) {
    MonarchBanner({{items.0.title}}, message: {{items.0.body}}, tone: {{items.0.tone|tone}})
    MonarchBanner({{items.1.title}}, tone: {{items.1.tone|tone}})
    MonarchBanner({{items.2.title}}, tone: {{items.2.tone|tone}}) {
        MonarchButton({{items.2.action.label}}, variant: {{items.2.action.variant|case}}, size: {{items.2.action.size|case}}) {}
    }
    MonarchBanner({{items.3.title}}, message: {{items.3.body}}, tone: {{items.3.tone|tone}})
}

examples.code:
VStack(spacing: MonarchTokens.Space.space3) {
    MonarchBanner("Sync scheduled", message: "Rook ID members refresh every 15 minutes.", tone: .info)
    MonarchBanner("Saved", tone: .success)
    MonarchBanner("Domain not verified", tone: .warning) {
        MonarchButton("Verify", variant: .secondary, size: .sm) {}
    }
    MonarchBanner("Payment failed", message: "Update the card to keep the workspace active.", tone: .danger)
}
